phase1.code:
fn main() {
    // ---- Passing ownership to functions ----
    let s1 = String::from("hello");
    take_ownership(s1);  // s1 is moved
    // println!("{}", s1);  // ERROR! s1 no longer owns the String

    // ---- Borrowing to functions ----
    let s2 = String::from("hello");
    borrow_string(&s2);  // s2 is borrowed
    println!("s2: {}", s2);  // Still valid

    // ---- Mutable borrowing to functions ----
    let mut s3 = String::from("hello");
    borrow_mut(&mut s3);  // s3 is mutably borrowed
    println!("s3: {}", s3);  // Modified

    // ---- Returning ownership ----
    let s4 = give_ownership();  // s4 owns the String
    println!("s4: {}", s4);

    // ---- Taking and returning ownership ----
    let s5 = String::from("hello");
    let s6 = take_and_return(s5);  // s5 is moved in, s6 is moved out
    println!("s6: {}", s6);
    // println!("{}", s5);  // ERROR! s5 was moved

    // ---- Copy types in functions ----
    let x = 5;
    take_copy(x);  // x is copied
    println!("x: {}", x);  // Still valid

    // ---- Multiple ownership patterns ----
    let s7 = String::from("hello");
    let (s8, len) = calculate_length(s7);  // Returns ownership and value
    println!("s8: {}, len: {}", s8, len);
}

fn take_ownership(s: String) {
    println!("take_ownership: {}", s);
}  // s is dropped here

fn borrow_string(s: &String) {
    println!("borrow_string: {}", s);
}

fn borrow_mut(s: &mut String) {
    s.push_str(", world");
}

fn give_ownership() -> String {
    let s = String::from("returned");
    s
}

fn take_and_return(s: String) -> String {
    println!("take_and_return: {}", s);
    s
}

fn take_copy(x: i32) {
    println!("take_copy: {}", x);
}

fn calculate_length(s: String) -> (String, usize) {
    let len = s.len();
    (s, len)
}

